import os
from pathlib import Path

base = Path(r'C:\AI-BS')
scripts = []
for p in base.rglob('*'):
    if any(part.startswith('.') or part in ['node_modules', 'dist', '_archive_v1', 'build', 'pyppeteer_env', 'venv'] for part in p.parts):
        continue
    if p.is_file() and p.suffix in ['.py', '.js', '.mjs', '.ps1', '.bat', '.sh']:
        scripts.append(p)

print('Total custom script files found:', len(scripts))

categories = {
    'telemetry_monitoring': [],
    'crypto_accounting_trading': [],
    'email_notifications': [],
    'document_spreadsheet_sync': [],
    'automation_webhooks': [],
    'hardware_wsl_mining': [],
    'frontend_react_ui': [],
}

for s in scripts:
    s_str = str(s).lower()
    if 'frontend' in s_str:
        categories['frontend_react_ui'].append(s)
    elif any(k in s_str for k in ['mine', 'peakminer', 'wsl', 'gpu', 'nvenc', 'vst', 'audio', 'chia']):
        categories['hardware_wsl_mining'].append(s)
    elif any(k in s_str for k in ['telemetry', 'watcher', 'ping', 'health', 'heartbeat', 'monitor']):
        categories['telemetry_monitoring'].append(s)
    elif any(k in s_str for k in ['crypto', 'trade', 'wallet', 'ledger', 'accounting', 'tax', 'cro', 'pearl', 'payout']):
        categories['crypto_accounting_trading'].append(s)
    elif any(k in s_str for k in ['email', 'mail', 'notification', 'alert']):
        categories['email_notifications'].append(s)
    elif any(k in s_str for k in ['drive', 'sheet', 'doc', 'context', 'calendar', 'sync']):
        categories['document_spreadsheet_sync'].append(s)
    else:
        categories['automation_webhooks'].append(s)

for cat, flist in categories.items():
    print(f'{cat}: {len(flist)} files')
